/* Geometry: a 28px marker column, the line centred under it, and rows whose first text line centres on the marker. */
.root { --marker: 28px; --marker-top: 8px; --line-gap: 4px; position: relative; display: grid; min-width: 0; color: var(--foreground); }
/* Inserting at the top pushes the rows down instead of the browser holding the scroll position still. */
.scroller { min-width: 0; overflow-anchor: none; }
@property --timeline-feather { syntax: "<length>"; inherits: false; initial-value: 0px; }
.scroller[data-scrolls] { max-height: var(--timeline-height); overflow-y: auto; overscroll-behavior: contain; scrollbar-color: var(--border-strong) transparent; scrollbar-width: thin; mask-image: linear-gradient(to bottom, #000 calc(100% - var(--timeline-feather)), transparent); transition: --timeline-feather var(--duration-standard) var(--ease-standard); }
/* While more updates wait below, the last visible row fades into the edge instead of being cut. */
.scroller[data-more] { --timeline-feather: 36px; }
.group { position: relative; }
.group[data-entering] { overflow: clip; }
/* Day labels stay pinned while their updates scroll under them. Set --timeline-surface when the feed sits on another surface. */
.day { position: sticky; z-index: 2; top: 0; display: flex; align-items: baseline; justify-content: space-between; gap: var(--space-3); padding: var(--space-2) var(--space-3) var(--space-2) 0; background: var(--timeline-surface, var(--surface)); color: var(--foreground); font-size: var(--text-sm); font-weight: 500; line-height: var(--leading-body); }
.count { color: var(--text-muted); font-size: var(--text-xs); font-weight: 400; font-variant-numeric: tabular-nums; }
.rolling { display: inline-flex; }
.place { position: relative; display: inline-flex; overflow: clip; overflow-clip-margin: .15em; }
.rise { position: relative; display: inline-flex; }
.riseLine { display: inline-block; white-space: nowrap; }
.list { margin: 0 0 var(--space-3); padding: 0; list-style: none; }

.item { position: relative; padding-left: calc(var(--marker) + var(--space-2)); }
.item[data-entering] { overflow: clip; }
.marker { position: absolute; z-index: 1; top: var(--marker-top); left: 0; display: grid; width: var(--marker); height: var(--marker); place-items: center; border-radius: var(--radius-pill); color: var(--text-secondary); }
.marker img { display: block; width: 100%; height: 100%; border-radius: inherit; object-fit: cover; }
/* A person's portrait sits on a hairline ring; a system event is a quiet node with its icon. */
.marker::after { content: ""; position: absolute; inset: 0; border: 1px solid color-mix(in oklch, var(--foreground) 10%, transparent); border-radius: inherit; pointer-events: none; }
.marker[data-tone] { background: var(--surface); }
.marker[data-tone="success"] { background: color-mix(in oklch, var(--success) 12%, var(--surface)); color: var(--success); }
.marker[data-tone="danger"] { background: color-mix(in oklch, var(--danger) 12%, var(--surface)); color: var(--danger); }
.marker svg { width: 14px; height: 14px; stroke-width: 2; }
/* The line runs from just under this marker to just above the next one and draws downward from its top. */
.segment { position: absolute; top: calc(var(--marker-top) + var(--marker) + var(--line-gap)); bottom: calc(var(--line-gap) - var(--marker-top)); left: calc(var(--marker) / 2 - .5px); width: 1px; background: var(--border-strong); transform-origin: 50% 0; }

.content { min-width: 0; }
.trigger { display: grid; width: 100%; grid-template-columns: minmax(0, 1fr) auto; align-items: start; column-gap: var(--space-3); margin: 0; padding: 12px var(--space-3); border: 0; border-radius: var(--radius-control); background: transparent; color: inherit; font: inherit; text-align: left; -webkit-tap-highlight-color: transparent; transition: background-color var(--duration-fast) var(--ease-standard); }
button.trigger { grid-template-columns: minmax(0, 1fr) auto 16px; cursor: pointer; }
@media (hover: hover) and (pointer: fine) { button.trigger:hover { background: var(--surface-muted); } }
button.trigger:active { background: var(--surface-muted); }
button.trigger:focus-visible { outline: 2px solid var(--focus-ring); outline-offset: -2px; }
.text { display: grid; min-width: 0; gap: 2px; }
.title { color: var(--text-secondary); font-size: var(--text-sm); line-height: 20px; }
.actor { color: var(--foreground); font-weight: 500; }
.meta { color: var(--text-muted); font-size: var(--text-xs); line-height: var(--leading-body); }
/* Times keep a steady column, so "9m" becoming "10m" never rewraps the title beside it. */
.time { display: flex; min-width: 2.75rem; justify-content: flex-end; color: var(--text-muted); font-size: var(--text-xs); line-height: 20px; font-variant-numeric: tabular-nums; white-space: nowrap; }
.chevron { display: grid; height: 20px; place-items: center; color: var(--text-muted); }
.detail { overflow: clip; overflow-clip-margin: 4px; }
.detailInner { padding: 0 var(--space-3) var(--space-4); color: var(--text-secondary); font-size: var(--text-sm); line-height: var(--leading-body); }

.srOnly { position: absolute; width: 1px; height: 1px; overflow: hidden; clip-path: inset(50%); white-space: nowrap; }

@media (max-width: 420px) { .trigger { column-gap: var(--space-2); padding-inline: var(--space-2); } .detailInner { padding-inline: var(--space-2); } }
@media (prefers-reduced-motion: reduce) { .trigger { transition: none; } .scroller[data-scrolls] { transition: --timeline-feather 150ms linear; } }
